#include <stdio.h>
int is_goal(int power) {
  return power >= 4 && power <= 7;
}
int main(void) {
  int goals = 0;
  for (int round = 0; round < 3; round++) {
    int power;
    scanf("%d", &power);
    goals = goals + is_goal(power);
  }
  printf("进球%d次\n", goals);
  return 0;
}

