int is_valid(int height) {
  return height >= 6;
}
int main(void) {
  int count = 0;
  for (int round = 0; round < 4; round++) {
    int height;
    scanf("%d", &height);
    if (is_valid(height)) {
      count++;
    }
  }
  printf("有效%d次\n", count);
  return 0;
}

